/**
 * Impronta della sostanza delle regole, non soltanto del numero di versione.
 * In precedenza bastava dimenticare di incrementare la versione per mantenere
 * verde un'evidenza di test riferita a codice ormai diverso.
 */
export const APR_RULE_SOURCE_FINGERPRINT = crypto.createHash("sha256").update(JSON.stringify({
  matrix: APR_RULE_TEST_MATRIX,
  businessDecisionLedger: { version: APR_BUSINESS_DECISION_LEDGER_VERSION, fingerprint: APR_BUSINESS_DECISION_LEDGER_FINGERPRINT },
  registry: ENEA_OPERATIONAL_REGISTRY.map((rule) => ({
    id: rule.id,
    step: rule.step,
    condition: rule.condition,
    sourcePrecedence: rule.sourcePrecedence,
    deterministicAction: rule.deterministicAction,
    outcome: rule.outcome,
    lifecycle: rule.lifecycle ?? null,
  })),
})).digest("hex");

export interface AprRuleMatrixEvidence {
  matrixVersion: typeof APR_RULE_TEST_MATRIX_VERSION;
  registryVersion: typeof ENEA_OPERATIONAL_REGISTRY_VERSION;
  verifiedAt: string;
  testCommand: string;
  passedKeys: string[];
  ruleProofs: Record<string, {
    fixtureId: string;
    independentAnalogFixtureId: string;
    sourceFingerprint: string;
    replayFingerprint: string;
    executionPath: string[];
    producedFields: string[];
    expectedOutcome: string;
    actualOutcome: string;
    positiveTest: string;
    negativeTest: string;
    rawReportRef: string;
    rawReportSha256: string;
    codeFingerprint: string;
    verifiedAt: string;
  }>;
  sourceFingerprint: string;
  testExitCode: 0;
  deployment?: {
    verifiedAt: string;
    builtBundleSha256: Readonly<Record<string, string>>;
    installedBundleSha256: Readonly<Record<string, string>>;
  };
}

export function evaluateRuleMatrix(evidence: AprRuleMatrixEvidence | null) {
  const evidenceCurrent = evidence?.matrixVersion === APR_RULE_TEST_MATRIX_VERSION
    && evidence.registryVersion === ENEA_OPERATIONAL_REGISTRY_VERSION
    && evidence.sourceFingerprint === APR_RULE_SOURCE_FINGERPRINT
    && evidence.testExitCode === 0;
  const passed = new Set(evidenceCurrent ? evidence.passedKeys.filter((key) => Boolean(evidence.ruleProofs?.[key])) : []);
  const deploymentVerified = evidenceCurrent && evidence.deployment
    && Object.keys(evidence.deployment.builtBundleSha256).length > 0
    && Object.entries(evidence.deployment.builtBundleSha256)
      .every(([name, digest]) => evidence.deployment?.installedBundleSha256[name] === digest);
  return APR_RULE_TEST_MATRIX.map((entry) => ({
    ...entry,
    status: !passed.has(entry.key)
      ? "pending_test" as const
      : deploymentVerified
        ? "active_tested_deployed" as const
        : "tested_not_deployed" as const,
  }));
}
